/**
 * Auto-eventing lab: events read from video by a detector that never sees the log, scored
 * against the log. The video is the synthetic match rendered top-down (labs/auto_eventing);
 * the results and the one-minute clip are generated by the lab and committed with the code.
 */
"use client";

import Link from "next/link";
import { useRef, useState } from "react";
import { clock, playerName } from "./data";
import lab from "./generated/auto-eventing.json";

type ClipEvent = { t: number; kind: "pass" | "carry" | "shot"; team: string | null; length_m: number; kmh: number; event_id: string | null };
type ShotRow = { event_id: string; clock: string; tracking_kmh: number | null; video_kmh: number; detected_as: string };
type Lab = {
  video: { fps: number; width: number; height: number; seconds: number; frames: number; clip: { from_s: number; to_s: number } };
  touches: { logged: number; found: number; recall: number; precision: number; unlogged_true: number };
  type_accuracy: number; team_accuracy: number;
  passes: { compared: number; length_mae_m: number; length_median_m: number; speed_mae_kmh: number };
  shots: { logged: number; matched: number; detected_as_shot: number; speed_mae_kmh: number; rows: ShotRow[] };
  possession: { log: number; video: number };
  clip_events: ClipEvent[];
};

const data = lab as unknown as Lab;
const CLIP_WEBM = new URL("./generated/auto-eventing.webm", import.meta.url).href;
const CLIP_MP4 = new URL("./generated/auto-eventing.mp4", import.meta.url).href;
const pct = (v: number, d = 1) => `${(v * 100).toFixed(d)}%`;
const TEAM = { nbr: "Northbridge", riv: "Riverside" } as Record<string, string>;
const KIND = { pass: "Pass", carry: "Carry", shot: "Shot" } as const;

export function AutoEventingLab() {
  const video = useRef<HTMLVideoElement>(null);
  const [now, setNow] = useState(data.video.clip.from_s);
  const { touches, passes, shots, possession } = data;
  const seen = data.clip_events.filter((e) => e.t <= now + 0.05);
  const current = seen.at(-1);
  const cards: [string, string, string][] = [
    ["Touches found", pct(touches.recall), `of ${touches.logged.toLocaleString("en-GB")} logged touches, ${pct(touches.precision)} of detections real`],
    ["Event type", pct(data.type_accuracy), "pass, carry or shot, against the log"],
    ["Team", pct(data.team_accuracy), "from the colour round the ball"],
    ["Pass length", `±${passes.length_mae_m.toFixed(2)} m`, `mean error over ${passes.compared} passes`],
    ["Ball speed", `±${passes.speed_mae_kmh.toFixed(1)} km/h`, "mean error over the same passes"],
    ["Shot speed", `±${shots.speed_mae_kmh.toFixed(1)} km/h`, `${shots.detected_as_shot} of ${shots.logged} shots found as shots`],
    ["Possession", `${pct(possession.video)} vs ${pct(possession.log)}`, "Northbridge, from the video vs the registered metric"],
  ];
  return (
    <>
      <div className="md-banner md-banner-info" role="note">
        <span className="md-banner-icon" aria-hidden="true">i</span>
        <span><strong>Synthetic video.</strong> No match footage is used: the synthetic match is rendered top-down, with sensor noise and the ball sometimes hidden. A detector that only sees the pixels finds the events, and the lab scores it against the event log. Real broadcast video would be far harder; this shows the pipeline and how it is checked.</span>
      </div>
      <div className="md-split">
        <section className="md-panel md-split-main" aria-labelledby="md-ae-video">
          <div className="md-panel-head"><h2 id="md-ae-video">Video in, events out</h2><span className="md-muted md-small">{clock(data.video.clip.from_s)}–{clock(data.video.clip.to_s)} · the corner and Okafor&apos;s header</span></div>
          <video ref={video} className="md-ae-video" controls muted playsInline preload="metadata" width={data.video.width} height={data.video.height}
            onTimeUpdate={(e) => setNow(data.video.clip.from_s + e.currentTarget.currentTime)}
            aria-describedby="md-ae-video-desc">
            <source src={CLIP_WEBM} type="video/webm" />
            <source src={CLIP_MP4} type="video/mp4" />
          </video>
          <p id="md-ae-video-desc" className="md-muted md-small">Top-down synthetic video, {data.video.fps} frames a second. The white dot is the ball; a coloured ring marks the team touching it (orange Northbridge, red Riverside), and stays with the ball while a player runs with it.</p>
          <p className="md-ae-now" role="status" aria-live="polite">
            {current ? <><span className="md-mono">{clock(current.t)}</span> {KIND[current.kind]} · {current.team ? TEAM[current.team] : "team not seen"} · {current.length_m} m · {current.kmh} km/h {current.event_id ? <span className="md-chip md-chip-verified">matches {current.event_id}</span> : <span className="md-chip md-chip-not-yet">not in the log</span>}</> : "Press play: events appear as the detector finds them."}
          </p>
        </section>
        <aside className="md-split-side" aria-label="Detected in this clip">
          <section className="md-panel" aria-labelledby="md-ae-list">
            <h2 id="md-ae-list">Detected in this clip</h2>
            <ol className="md-ae-events">
              {data.clip_events.map((e) => (
                <li key={e.t} className={e.t <= now + 0.05 ? "md-ae-seen" : undefined}>
                  <button type="button" onClick={() => { if (video.current) { video.current.currentTime = Math.max(0, e.t - data.video.clip.from_s - 0.5); } }}>
                    <span className="md-mono">{clock(e.t)}</span><span>{KIND[e.kind]} · {e.team ? TEAM[e.team] : "?"} · {e.kmh} km/h</span>{e.event_id && <span className="md-mono md-subtle">{e.event_id}</span>}
                  </button>
                </li>
              ))}
            </ol>
          </section>
        </aside>
      </div>
      <section className="md-panel" aria-labelledby="md-ae-score">
        <div className="md-panel-head"><h2 id="md-ae-score">Scored against the log</h2><span className="md-muted md-small">Whole replay · {data.video.frames.toLocaleString("en-GB")} frames · {clock(data.video.seconds)}</span></div>
        <ul className="md-ae-cards">
          {cards.map(([label, value, note]) => <li key={label}><span className="md-muted md-small">{label}</span><strong className="md-mono">{value}</strong><span className="md-small">{note}</span></li>)}
        </ul>
        <details className="md-table-toggle">
          <summary>Every shot: video speed against the log&apos;s synthetic tracking</summary>
          <table className="md-table">
            <caption className="md-visually-hidden">Shot speeds read from the video and from the log</caption>
            <thead><tr><th scope="col">Shot</th><th scope="col">Clock</th><th scope="col">Log (tracking)</th><th scope="col">Video</th><th scope="col">Read as</th></tr></thead>
            <tbody>{shots.rows.map((r) => <tr key={r.event_id}><td className="md-mono">{r.event_id}</td><td className="md-mono">{r.clock}</td><td className="md-mono">{r.tracking_kmh?.toFixed(1) ?? "–"} km/h</td><td className="md-mono">{r.video_kmh.toFixed(1)} km/h</td><td>{r.detected_as}</td></tr>)}</tbody>
          </table>
        </details>
        <p className="md-muted md-small">
          How it works: the detector finds the ball as the brightest compact blob in each frame, fills gaps of up to three hidden frames, and marks a touch where the ball&apos;s velocity over the next four frames differs most from the last four. Between touches it measures length and speed from the first unbroken run of movement; a fast strike that reaches or heads at a goal is a shot, a ball the ringed player keeps is a carry, the rest are passes. {touches.unlogged_true} true touches are not in the log (saves and rebounds the renderer adds after shots). Source and method: <code className="md-mono">labs/auto_eventing</code>. {playerName("nbr-09")}&apos;s header is in the clip.
        </p>
        <p className="md-small"><Link className="md-link" href="/match/nbr-riv/live">Back to Live Intelligence</Link></p>
      </section>
    </>
  );
}
